        "Y9gukafwaFEAEqG0": {
          "name": "Ressonância",
          "description": "30 pés (9 metros). Todos os fogos-fátuos vibram em uma frequência sintonizada com seu elemento, ressoando e fortalecendo todas as criaturas e efeitos que compartilham essa característica. Uma criatura na área ganha um bônus de status de +1 nas jogadas de ataque e dano para efeitos com a característica planta ou madeira; uma criatura com a característica elemental e a característica planta ou madeira ganha este bônus em todas as jogadas de ataque e dano. Para tufos de madeira, este bônus também se aplica a armas de madeira não-mágicas, como cajados e porretes."
        },
