      "actions": {
        "sCB4c0FpXN7ZgEHE": {
          "name": "Aroma de Cristal",
          "description": "Um cullitox pode sentir cristais ou gemas dentro de 60 pés (18 metros) como se estivesse usando a habilidade de perfume."
        },
        "agAnzTLuLv3ofRDa": {
          "name": "Passo de rocha",
          "description": "O cullitox se transforma em rocha adjacente que é grande o suficiente para acomodá-lo. Então, o cullitox detecta rochas semelhantes ou maiores dentro de 60 pés (18 metros) e emerge de uma delas. O Cullitox não pode usar esta habilidade novamente por 1 minuto."
        },
        "zdHbmBbUYAU1VVSI": {
          "name": "Afundar na pedra",
          "description": "Os espinhos disparados da cauda de um cullitox em pedra, prendendo os inimigos no lugar. Inimigos que estão sobre ou adjacentes a uma superfície de pedra e que são atingidos por um golpe crítico em um golpe de cauda são imobilizados. O DC para Escapar CD 17 é 17."
        }
      },
