        "93DuUwpGPYBXrzCb": {
          "name": "Malhador",
          "description": "Um cervo pintado ganha +5 de bônus de circunstância nas jogadas de dano contra criaturas que ele agarrou."
        },
        "KSf86thTKJea2Lup": {
          "name": "Dança Pintada",
          "description": "O cervo sacode o revestimento de madeira ao longo de seu corpo em um barulho cacofônico que faz dançar seus padrões pintados. Todas as criaturas dentro de 60 pés (18 metros) do cervo pintado que puderem vê-lo ou ouvi-lo devem tentar um teste de resistência (vontade, dc:28); uma criatura Agarrada pelo cervo sofre –4 de penalidade de circunstância em seu teste de resistência. Independentemente do resultado do teste, cada criatura fica temporariamente imune por 1 hora.\nSucesso Crítico A criatura não é afetada.\nSucesso A criatura fica fascinada pelo cervo pintado por 1 rodada.\nFalha A criatura fica Atordoada 2 e fascinada pelo cervo pintado enquanto ele estiver atordoado.\nFalha Crítica Como falha, exceto Atordoado 4."
        },
