          "description": "Quando um anemos lança um ritual, ele mesmo realiza todos os aspectos do ritual, comandando seus ventos para completar todos os componentes do ritual. Eles devem cumprir quaisquer requisitos para os conjuradores adicionais do ritual e devem tentar os testes normalmente realizados por conjuradores adicionais. Além disso, os anemoi podem lançar rituais mais rápido que o normal. Se um ritual tiver um tempo de execução medido em dias, eles poderão lançá-lo em igual número de horas."
